        '* ⚠️ Important Issues: ' + m.bold(String(issueCounts.important)) + '\n' +
        '* 💡 Suggestions: ' + m.bold(String(issueCounts.suggestions)) + '\n' +
        '* 🪶 Nits: ' + m.bold(String(issueCounts.nits)) + '\n' +
        '* 📋 Digest lines: ' + m.bold(String(issueCounts.digest)) + '\n\n';
