test('applyReviewFilter — a demote on a file-referenced comment rewrites the comment file', function() {
    var writes = [];
    var commentFile = 'outputs/pr_review_comments/c1.md';
    var fileMap = {
        'outputs/pr_review_filter.json': JSON.stringify({ verdicts: [
