        console.log('🧯 review filter CLI run completed: ' + String(out || '').substring(0, 300));
        return true;
    } catch (e) {
        console.warn('🧯 review filter CLI failed (gh-1403 fail-open, running unfiltered): ' + (e.message || e));
        return false;
    }
}

